module benchmark/solution

import std/json (Json, JNull, JBool, JNumber, JString, JArray, JObject, decode, encode, jint, js)
import std/list (map)
import std/string (join)

pure func setField(fields: [{key: string, value: Json}], k: string, v: Json) -> [{key: string, value: Json}] =
  map(\f. if f.key == k then {key: f.key, value: v} else f, fields)

func render(j: Json) -> string =
  match j {
    JObject(fields) => "{${join(", ", map(\f. "${encode(js(f.key))}: ${render(f.value)}", fields))}}",
    JArray(items) => "[${join(", ", map(\x. render(x), items))}]",
    other => encode(other)
  }

export func main() -> () ! {IO} {
  let src = "{\"name\": \"alice\", \"age\": 30, \"role\": \"engineer\"}";
  match decode(src) {
    Ok(JObject(fields)) => {
      let updated = setField(setField(fields, "age", jint(31)), "role", js("senior engineer"));
      println(render(JObject(updated)))
    },
    Ok(_) => println("not an object"),
    Err(e) => println("parse error: ${e}")
  }
}

